#!/usr/bin/env node
/*
 * Paper ↔ app mapping check.  node scripts/check-paper-mapping.js
 *
 * A child does a set on paper, photographs it, and the app maps each PRINTED
 * problem number back to an item in the bank. That only works if the printed
 * sheet and `pOnPaper` in index.html build the same ordered list. They are
 * generated by different tools, so nothing but this script keeps them honest —
 * and when they drift the failure is silent: answers land on the wrong
 * problems and a child is marked wrong for work they got right.
 *
 * CONTRIBUTING.md states the shared contract:
 *   1. dedupe by question text, in bank order
 *   2. group Warm-Up (t0) -> Core (t1) -> Challenge (t2)
 *   3. number 1..N straight through the sheet
 *
 * This rebuilds that list from the curriculum and compares it, item by item,
 * against what is actually printed in every worksheet page.
 */
const fs = require("fs");
const path = require("path");
const ROOT = path.resolve(__dirname, "..");
process.chdir(ROOT);

// ── the app's ordering, mirrored from index.html pOnPaper ────────────────
function sheetFor(set) {
  const seen = new Set(), uniq = [];
  set.items.forEach((it, i) => {
    const q = String(it.q).replace(/\s+/g, "").toLowerCase();
    if (seen.has(q)) return;
    seen.add(q); uniq.push({ it, i });
  });
  const sheet = [];
  [0, 1, 2].forEach(t => uniq.forEach(x => { if (x.it.t === t) sheet.push({ i: x.i, n: sheet.length + 1, q: x.it.q }); }));
  return sheet;
}

// ── load the curriculum the way the browser does ─────────────────────────
// The file list is READ FROM index.html rather than hardcoded. It used to be a
// literal array, and the subject-registry change broke it the moment
// registry.js started calling window.Subjects.register: subjects.js was not in
// the list, so the load threw and this reported the paper mapping as broken
// when nothing was wrong with it. Deriving the list means adding a subject can
// never again produce a false failure here.
const sb = { __CURR: {} }; sb.window = sb;
const curriculumFiles = [...fs.readFileSync("index.html", "utf8")
  .matchAll(/<script src="([^"]+)"/g)]
  .map(m => m[1].replace(/^\.\//, "").split("?")[0])
  .filter(s => s.startsWith("curriculum/"));
if (!curriculumFiles.length) {
  console.log("  FAIL  index.html declares no curriculum/*.js scripts");
  process.exit(1);
}
for (const f of curriculumFiles) {
  new Function("window", "console", fs.readFileSync(f, "utf8"))(sb, { log() {}, warn() {}, error() {} });
}
// Sets are addressed by id, not title — 25 titles are duplicated across the
// two years ("Mid-Unit Quiz", "Powers of Ten"...), so matching on title alone
// silently compares a Year-Two page against a Year-One bank.
//   Y1 unit 1 week 1 : p{P}          Y1 : u{U}w{W}p{P}  (week 1: u{U}p{P})
//   Y2               : y5u{U}w{W}p{P}                   (week 1: y5u{U}p{P})
const byId = new Map();
for (const s of sb.__CURR.ALL_SETS || []) byId.set(s.id, s);
function resolve(file, label) {
  const m = label.match(/^(\d+)\.(\d+)/);
  if (!m) return null;
  const week = +m[1], page = +m[2];
  const u = (file.match(/Unit (\d+)/) || [])[1];
  if (!u) return null;
  const unit = +u, y2 = /^Y2 /.test(file);
  const cands = y2
    ? [week === 1 ? `y5u${unit}p${page}` : null, `y5u${unit}w${week}p${page}`]
    : [week === 1 && unit === 1 ? `p${page}` : null,
       week === 1 ? `u${unit}p${page}` : null, `u${unit}w${week}p${page}`];
  for (const c of cands) if (c && byId.has(c)) return byId.get(c);
  return null;
}

/* Pages whose label is not "N.N Something" — the Friday tests, the mid-unit
 * quizzes, the Thursday error-journal sweeps, the enrichment duels — were
 * skipped entirely by the id-pattern resolver, so they were never regenerated
 * AND never checked. That is the same shape of hole as the tier regex: a whole
 * class of page quietly outside the tooling. These carry the tests, which are
 * the worst pages to mis-map.
 *
 * So when the id pattern does not match, fall back to matching the page title
 * against the set title inside the same unit. "· back" is a reverse side of the
 * page before it and resolves to the same set — the numbering continues across
 * the two sides. */
const deent = s => String(s).replace(/&amp;/g, "&").replace(/&nbsp;/g, " ")
  .replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/\s+/g, " ").trim();
function resolveByTitle(file, label) {
  const u = (file.match(/Unit (\d+)/) || [])[1];
  if (!u) return null;
  const unit = +u, y2 = /^Y2 /.test(file);
  const want = deent(label)
    .replace(/^(Mon|Tue|Wed|Thu|Fri)\s+/i, "")
    .replace(/\s*·\s*back\s*$/i, "")
    .toLowerCase();
  if (!want) return null;
  /* Titles are NOT unique inside a unit — "Mission 07 Test" is both u7w3p5 and
   * u7w5p5, and "Chance as a Number" is both u7p4 and u7w2p4. Silently taking
   * the first match would write one set's questions onto the other's page,
   * which is the failure this whole exercise exists to prevent. So an
   * ambiguous title resolves to nothing and the page is left alone and
   * reported, rather than being confidently rewritten with the wrong content. */
  const pre = y2 ? `y5u${unit}` : `u${unit}`;
  const hits = (sb.__CURR.ALL_SETS || []).filter(s => {
    const id = String(s.id);
    return id.startsWith(pre) && y2 === id.startsWith("y5")
      && deent(s.title || "").toLowerCase() === want;
  });
  return hits.length === 1 ? hits[0] : null;
}

// Numbered problems appear in THREE styles, one per tier, and matching only
// the first is how a generator and a checker sharing this regex both went
// blind to two thirds of every page:
//   Warm-Up   font-size:9.5px   ">1</span>"    no trailing dot
//   Core      font-size:10px    ">13.</span>"  trailing dot, hint span after
//   Challenge font-size:10.5px  ">25.</span>"  trailing dot
// The question runs from &nbsp; to the next tag, which stops before Core's
// hint span and before the dotted answer rule.
const PROBLEM_RX = /font-size:(?:9\.5|10|10\.5)px[^>]*>(\d+)\.?<\/span>(&nbsp;\s*)([^<]*)/g;

const norm = s => String(s)
  .replace(/&nbsp;/g, " ").replace(/&times;/g, "×").replace(/&divide;/g, "÷")
  .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
  .replace(/<[^>]+>/g, "").replace(/\s+/g, " ").trim();

let fails = 0, pages = 0, matched = 0, problems = 0;
const skipped = [];

for (const file of fs.readdirSync(".").filter(f => /Worksheets\.dc\.html$/.test(f))) {
  const html = fs.readFileSync(file, "utf8");
  // one <section class="page"> per printed side, labelled with the set title
  const sections = html.split(/<section class="page"/).slice(1);
  for (const sec of sections) {
    const label = (sec.match(/data-screen-label="([^"]*)"/) || [])[1];
    if (!label) continue;
    // "1.1 Arrays Become Area" -> "Arrays Become Area"
    const set = resolve(file, label) || resolveByTitle(file, label);
    if (!set) { skipped.push(`${file}: "${label}"`); continue; }
    // printed problems: <span ...>N</span>&nbsp; QUESTION</div>
    const printed = [...sec.matchAll(PROBLEM_RX)]
      .map(m => ({ n: +m[1], q: norm(m[3]) }));
    if (!printed.length) continue;
    pages++;
    const expect = sheetFor(set);
    // The sheet spans two pages; check the printed numbers against the same
    // positions in the rebuilt list.
    let bad = 0, firstBad = null;
    for (const p of printed) {
      problems++;
      const e = expect[p.n - 1];
      if (!e) { bad++; firstBad = firstBad || `#${p.n} printed but the bank rebuilds only ${expect.length} items`; continue; }
      if (norm(e.q) !== p.q) {
        bad++;
        firstBad = firstBad || `#${p.n} prints "${p.q}" but the app maps that number to "${norm(e.q)}"`;
      }
    }
    if (bad) { console.log(`  FAIL  ${file} · ${label}: ${bad}/${printed.length} mismatched — ${firstBad}`); fails++; }
    else matched++;
  }
}

console.log("");
console.log(`  pages checked: ${pages} · problems compared: ${problems} · pages clean: ${matched}`);
if (skipped.length) {
  console.log(`  note: ${skipped.length} page(s) had no matching set by title (cover/reference pages):`);
  skipped.slice(0, 4).forEach(s => console.log(`        ${s}`));
}
console.log("-".repeat(52));
if (fails) { console.log(`RESULT: ${fails} page(s) MISMATCHED — scanned answers would land on the wrong problems`); process.exit(1); }
console.log("RESULT: printed numbering matches the app's mapping on every page");
